/**
 * The issue list filter vocabulary of docs/adr/0009-issue-list-filters.md,
 * exercised through the three places that must agree on it: the URL codec, the
 * filter schema and the listing itself (service + repository).
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import {
  issueFilterToParams,
  parseIssueFilterParams,
} from "@/hooks/issue-filter-params";
import { exportIssuesSchema } from "@/schemas/export";
import { issueFilterSchema } from "@/schemas/issue";
import * as issueService from "@/server/services/issue-service";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IsoTimestamp, LabelId } from "@/types/common";
import type { Issue, IssueFilter, IssueStatus } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;
let bug: LabelId;
let regression: LabelId;

const byTitle = new Map<string, Issue>();

/** The page flow: URL → codec → schema → service. */
async function listFromQuery(query: string, as = tenant.actors.member) {
  const filter = issueFilterSchema.parse({
    ...parseIssueFilterParams(new URLSearchParams(query)),
    orgId: tenant.org.id,
    limit: 100,
  });
  const page = await issueService.listIssues(as, filter);
  return { titles: page.items.map((issue) => issue.title).sort(), total: page.total };
}

async function add(
  title: string,
  extra: {
    status?: IssueStatus;
    assignee?: "owner" | "member" | null;
    dueAt?: string | null;
    labels?: readonly LabelId[];
    archived?: boolean;
  } = {},
) {
  const created = await issueService.createIssue(tenant.actors.owner, {
    ...issueInput(tenant.org.id, tenant.project.id, {
      title,
      assigneeId:
        extra.assignee === undefined || extra.assignee === null
          ? null
          : tenant.userIds[extra.assignee],
      dueAt: extra.dueAt ?? null,
    }),
    labelIds: [...(extra.labels ?? [])],
  });
  if (extra.status !== undefined && extra.status !== "backlog") {
    await issueRepo.setIssueStatus(tenant.org.id, created.id, extra.status);
  }
  if (extra.archived === true) {
    await issueRepo.archiveIssue(tenant.org.id, created.id);
  }
  byTitle.set(title, created);
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("filters");

  const mk = async (name: string) =>
    (await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name,
      color: "#112233",
      description: null,
    })).id;
  bug = await mk("bug");
  regression = await mk("regression");
  const other = await mk("other");

  await add("mine-todo", { status: "todo", assignee: "member" });
  await add("mine-done", { status: "done", assignee: "member" });
  await add("theirs-todo", { status: "todo", assignee: "owner" });
  await add("nobody-backlog", { status: "backlog" });
  await add("nobody-canceled", { status: "canceled" });
  await add("both-labels", { labels: [bug, regression] });
  await add("bug-only", { labels: [bug] });
  await add("regression-and-other", { labels: [regression, other] });
  await add("due-early", { dueAt: "2026-03-01T08:00:00.000Z" });
  await add("due-on-day-late", { dueAt: "2026-03-02T23:30:00.000Z" });
  await add("due-on-day-midnight", { dueAt: "2026-03-02T00:00:00.000Z" });
  await add("due-next-day", { dueAt: "2026-03-03T00:00:00.000Z" });
  await add("archived-one", { archived: true, status: "todo" });
  await add("archived-two", { archived: true, assignee: "member" });
});

afterAll(() => {
  cleanup();
});

describe("issue list filters — assignee", () => {
  it("assignee=me lists the acting user's issues, whoever acts", async () => {
    const asMember = await listFromQuery("assignee=me", tenant.actors.member);
    expect(asMember.titles).toEqual(["mine-done", "mine-todo"]);

    const asOwner = await listFromQuery("assignee=me", tenant.actors.owner);
    expect(asOwner.titles).toEqual(["theirs-todo"]);
    expect(asOwner.total).toBe(1);
  });

  it("assignee=none lists only unassigned issues", async () => {
    const { titles, total } = await listFromQuery("assignee=none&status=todo,backlog,canceled");
    expect(titles).toEqual(["nobody-backlog", "nobody-canceled"].sort().concat([]).sort());
    expect(total).toBe(titles.length);
    expect(titles).not.toContain("mine-todo");
  });

  it("assignee=none never matches an assigned issue", async () => {
    const { titles } = await listFromQuery("assignee=none");
    expect(titles).not.toContain("mine-todo");
    expect(titles).not.toContain("theirs-todo");
    expect(titles).toContain("nobody-backlog");
  });

  it("omitting assignee does not filter on it", async () => {
    const { titles } = await listFromQuery("status=todo");
    expect(titles).toEqual(["mine-todo", "theirs-todo"]);
  });

  it("author=me resolves against the acting user too", async () => {
    const { total } = await listFromQuery("author=me", tenant.actors.owner);
    expect(total).toBeGreaterThan(0);
    const none = await listFromQuery("author=me", tenant.actors.member);
    expect(none.total).toBe(0);
  });

  it("the schema accepts me and the codec passes it through unchanged", () => {
    expect(parseIssueFilterParams(new URLSearchParams("assignee=me")).assigneeId).toBe("me");
    expect(
      issueFilterSchema.parse({ orgId: tenant.org.id, assigneeId: "me" }).assigneeId,
    ).toBe("me");
    expect(issueFilterToParams({ assigneeId: "me" }).assignee).toBe("me");
  });
});

describe("issue list filters — status groups", () => {
  it("the codec expands open and closed", () => {
    expect(parseIssueFilterParams(new URLSearchParams("status=open")).status).toEqual([
      "backlog",
      "todo",
      "in_progress",
      "in_review",
    ]);
    expect(parseIssueFilterParams(new URLSearchParams("status=closed")).status).toEqual([
      "done",
      "canceled",
    ]);
    expect(
      parseIssueFilterParams(new URLSearchParams("status=done,open,nonsense,todo")).status,
    ).toEqual(["done", "backlog", "todo", "in_progress", "in_review"]);
  });

  it("the schema accepts groups and still refuses unknown values", () => {
    expect(
      issueFilterSchema.safeParse({ orgId: tenant.org.id, status: ["open", "closed", "todo"] })
        .success,
    ).toBe(true);
    expect(issueFilterSchema.safeParse({ orgId: tenant.org.id, status: ["nonsense"] }).success).toBe(
      false,
    );
    expect(
      exportIssuesSchema.safeParse({ orgId: tenant.org.id, status: ["open"] }).success,
    ).toBe(true);
  });

  it("a group and its expansion list the same issues, at the repository too", async () => {
    const viaGroup = await issueRepo.listIssues({
      orgId: tenant.org.id,
      status: ["open"],
      limit: 100,
    });
    const viaList = await issueRepo.listIssues({
      orgId: tenant.org.id,
      status: ["backlog", "todo", "in_progress", "in_review"],
      limit: 100,
    });
    expect(viaGroup.items.map((i) => i.id).sort()).toEqual(viaList.items.map((i) => i.id).sort());
    expect(viaGroup.total).toBe(viaList.total);

    const closed = await listFromQuery("status=closed");
    expect(closed.titles).toEqual(["mine-done", "nobody-canceled"]);
  });
});

describe("issue list filters — labels are all-of", () => {
  it("lists only issues carrying every label, and counts exactly those", async () => {
    const { titles, total } = await listFromQuery(`label=${bug},${regression}`);
    expect(titles).toEqual(["both-labels"]);
    expect(total).toBe(1);
  });

  it("a single label still matches every issue that has it", async () => {
    const { titles, total } = await listFromQuery(`label=${bug}`);
    expect(titles).toEqual(["bug-only", "both-labels"]);
    expect(total).toBe(2);
  });

  it("a repeated label does not raise the bar", async () => {
    const { titles } = await listFromQuery(`label=${bug},${bug}`);
    expect(titles).toEqual(["bug-only", "both-labels"]);
  });
});

describe("issue list filters — due before", () => {
  it("accepts a calendar date in the codec and the schema", () => {
    const filter = parseIssueFilterParams(new URLSearchParams("due_before=2026-03-02"));
    expect(filter.dueBefore).toBe("2026-03-02");
    expect(
      issueFilterSchema.safeParse({ orgId: tenant.org.id, dueBefore: "2026-03-02" }).success,
    ).toBe(true);
    expect(
      issueFilterSchema.safeParse({ orgId: tenant.org.id, dueBefore: "2026-02-30" }).success,
    ).toBe(false);
    expect(
      issueFilterSchema.safeParse({ orgId: tenant.org.id, dueBefore: "soon" }).success,
    ).toBe(false);
  });

  it("drops a due_before the schema would refuse", () => {
    expect("dueBefore" in parseIssueFilterParams(new URLSearchParams("due_before=soon"))).toBe(false);
    expect("dueBefore" in parseIssueFilterParams(new URLSearchParams("due_before=2026-02-30"))).toBe(
      false,
    );
  });

  it("a date includes the whole day and everything earlier", async () => {
    const { titles, total } = await listFromQuery("due_before=2026-03-02");
    expect(titles).toEqual(["due-early", "due-on-day-late", "due-on-day-midnight"]);
    expect(total).toBe(3);
  });

  it("a timestamp stays strictly before that instant", async () => {
    const at = await listFromQuery("due_before=2026-03-02T00:00:00.000Z");
    expect(at.titles).toEqual(["due-early"]);

    const after = await listFromQuery("due_before=2026-03-02T23:30:00.001Z");
    expect(after.titles).toEqual(["due-early", "due-on-day-late", "due-on-day-midnight"]);

    const noMillis = await listFromQuery("due_before=2026-03-02T00:00:00Z");
    expect(noMillis.titles).toEqual(["due-early"]);
  });

  it("issues without a due date never match", async () => {
    const { titles } = await listFromQuery("due_before=2099-01-01");
    expect(titles).not.toContain("nobody-backlog");
    expect(titles).toContain("due-next-day");
  });

  it("the repository reads a date directly as well", async () => {
    const page = await issueRepo.listIssues({
      orgId: tenant.org.id,
      dueBefore: "2026-03-01" as IsoTimestamp,
      limit: 100,
    });
    expect(page.items.map((i) => i.title)).toEqual(["due-early"]);
  });
});

describe("issue list filters — archived", () => {
  it("absent lists live issues only", async () => {
    const { titles } = await listFromQuery("");
    expect(titles).not.toContain("archived-one");
    expect(titles).not.toContain("archived-two");
  });

  it("archived=1 lists archived alongside live", async () => {
    const { titles, total } = await listFromQuery("archived=1");
    expect(titles).toContain("archived-one");
    expect(titles).toContain("mine-todo");
    expect(total).toBe(byTitle.size);
  });

  it("archived=only lists archived issues and nothing else", async () => {
    const { titles, total } = await listFromQuery("archived=only");
    expect(titles).toEqual(["archived-one", "archived-two"]);
    expect(total).toBe(2);
  });

  it("archived=only composes with the other dimensions", async () => {
    const { titles, total } = await listFromQuery("archived=only&assignee=me");
    expect(titles).toEqual(["archived-two"]);
    expect(total).toBe(1);
  });

  it("round-trips through the URL and the schema", () => {
    const filter: IssueFilter = { includeArchived: "only" };
    expect(issueFilterToParams(filter)).toEqual({ archived: "only" });
    expect(parseIssueFilterParams(new URLSearchParams("archived=only"))).toEqual(filter);
    expect(
      issueFilterSchema.parse({ orgId: tenant.org.id, includeArchived: "only" }).includeArchived,
    ).toBe("only");
    expect(
      issueFilterSchema.safeParse({ orgId: tenant.org.id, includeArchived: "sometimes" }).success,
    ).toBe(false);
  });
});

describe("issue list filters — the total", () => {
  it("counts exactly the matches, across pages", async () => {
    const filter = issueFilterSchema.parse({
      orgId: tenant.org.id,
      ...parseIssueFilterParams(new URLSearchParams("status=open&archived=1")),
      limit: 2,
    });
    const first = await issueService.listIssues(tenant.actors.member, filter);
    expect(first.items).toHaveLength(2);
    const all = await issueService.listIssues(tenant.actors.member, { ...filter, limit: 100 });
    expect(first.total).toBe(all.items.length);
    expect(all.total).toBe(all.items.length);
  });
});

